/**
 * AUTHORING-MODEL COMPARISON — pick the model on evidence, blind.
 *
 * Eight representative beats (one per design concept, covering a number
 * name, an analogy, a CHECK_MY_WORK and a hook) are generated by each
 * candidate model with the SAME prompt and judged by the SAME mechanical
 * rules the production author enforces (src/lib/authorGuards.ts +
 * src/lib/scriptDistance.ts).
 *
 * Output:
 *   docs/review/model-comparison.md — versions labelled A/B/C per beat,
 *   model mapping only at the bottom, so the Sinhala is judged blind.
 *   stdout — violations, similarity, token spend per model, projections.
 *
 *   npm run compare:authors
 */
import { GoogleGenAI } from "@google/genai";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { LESSON_1_NUMBERS_STEPS } from "../src/data/lessons/lesson1-numbers";
import { degenerateBeatProblems, substituteNumbers, validateSay, type Problem } from "../src/lib/authorGuards";
import { MAX_JACCARD, charNgrams, sentencesOf, stripOfficial, surfaceSimilarity } from "../src/lib/scriptDistance";
import type { DesignConceptTag, LessonDesign, ConceptDesign } from "../src/lib/lessonDesign";
import { withRetry } from "./lib/geminiRetry";

const CANDIDATE_MODELS = [
  process.env.GEMINI_AUTHOR_MODEL ?? "gemini-3.1-pro-preview",
  "gemini-3.6-flash",
  "gemini-flash-latest",
];

const DESIGN_PATH = path.join(process.cwd(), "..", "docs", "design", "maths-5-1.json");
const STYLE_PATH = path.join(process.cwd(), "..", "docs", "design", "style-card.md");
const TRANSCRIPT_PATH = path.join(process.cwd(), "src/data/lessons/lesson1-teaching-plan-full.json");
const OUT_PATH = path.join(process.cwd(), "..", "docs", "review", "model-comparison.md");

/** One brief per concept; together they cover number-name, analogy, CHECK_MY_WORK and hook. */
const BRIEFS: Array<{ concept: DesignConceptTag; label: string; instructions: string; type: string }> = [
  {
    concept: "readWrite4Digit",
    label: "hook",
    type: "HOOK",
    instructions:
      "Write the concept's OPENING HOOK: one everyday moment from a Sri Lankan child's life that lands on a " +
      "4-digit number, ending in a small question (pauseType ASK with expectedAnswer, or SOFT_CHECK).",
  },
  {
    concept: "placeValue4Digit",
    label: "abacus reading with a number name",
    type: "EXPLAIN",
    instructions:
      "The abacus shows the official example {number:5421}. Read it place by place — beads, digit, place, " +
      "value — ending with the full number name. Board: abacus digits [5,4,2,1].",
  },
  {
    concept: "expandedForm4Digit",
    label: "expanding an official example",
    type: "EXPLAIN",
    instructions:
      "Walk the official worked example: {number:6831} written in expanded form as thousands + hundreds + " +
      "tens + ones. Board: a text card showing 6 831 = 6 000 + 800 + 30 + 1.",
  },
  {
    concept: "beyond9999",
    label: "the 9999+1 moment",
    type: "EXPLAIN",
    instructions:
      "Teach the lesson's core fact: what comes after {number:9999} — {number:10000}, with its name. Build " +
      "anticipation the way the technique sequence describes.",
  },
  {
    concept: "digitGroupingRule",
    label: "grouping in threes, with the analogy",
    type: "EXPLAIN",
    instructions:
      "Teach the digit-grouping rule (a space every three digits from the ones place) USING the concept's " +
      "everyday analogy (analogyDomain — pick one from the allowed list). Board: a text card contrasting " +
      "26147 and 26 147.",
  },
  {
    concept: "tenThousandsPlace",
    label: "introducing the new place",
    type: "EXPLAIN",
    instructions:
      "Introduce දස දහසස්ථානය with the official example {number:26147} in the place-value table — which " +
      "digit sits there and what it is worth.",
  },
  {
    concept: "placeValueTable5Digit",
    label: "a real ask on an official card",
    type: "ASK",
    instructions:
      "Ask ONE real question about the official card number {number:25602}: which digit is in a named place " +
      "(your choice). pauseType ASK, expectedAnswer set to the digit.",
  },
  {
    concept: "expandedForm5Digit",
    label: "check my work",
    type: "CHECK_MY_WORK",
    instructions:
      "Zara expands the official example {number:68507} on the board but makes ONE deliberate plausible " +
      "error (e.g. the zero place dropped or wrong). She asks the child to find her mistake. Set errorPlanted " +
      "and expectedAnswer.",
  },
];

const BEAT_SCHEMA = {
  type: "object",
  properties: {
    say: { type: "string", description: "Spoken Sinhala. Numbers ONLY as {number:26147} markers. {address} allowed." },
    pauseType: { type: "string", description: "RHETORICAL | SOFT_CHECK | ASK | NONE" },
    board: { type: "object", properties: { kind: { type: "string" }, text: { type: "string" }, digits: { type: "array", items: { type: "number" } } }, required: ["kind"] },
    expectedAnswer: { type: "string" },
    errorPlanted: { type: "string" },
    analogyDomain: { type: "string" },
  },
  required: ["say", "pauseType", "board"],
} as const;

const ANALOGY_DOMAINS = [
  "school van fare", "cricket score", "coins in a till", "kottu price",
  "mangoes in a basket", "bus ticket", "pola vegetables", "exercise books in a stack",
];

interface GenerationResult {
  model: string;
  brief: (typeof BRIEFS)[number];
  say: string;
  spoken: string;
  analogyDomain: string;
  sentenceCount: number;
  maxSentenceWords: number;
  violations: string[];
  maxJaccard: number;
  closest: string;
  inputTokens: number;
  outputTokens: number;
  thinkingTokens: number;
  failed?: string;
}

function buildPrompt(styleCard: string, design: LessonDesign, concept: ConceptDesign, brief: (typeof BRIEFS)[number]): string {
  return [
    "You are writing ONE beat of an ORIGINAL Sinhala lesson script for Zara, a warm voice tutor for one",
    "Grade 5 child. A recorded teacher's transcript exists for this material; your sentences are checked",
    "against it and rejected if close — write like a different teacher teaching the same official material.",
    "",
    "ABSOLUTE RULES:",
    "- Numbers: write EVERY number as a {number:26147} marker — never digits, never a Sinhala number name.",
    `- NEVER use these numbers: ${design.denylistNumbers.join(", ")}.`,
    "- At most 14 words per sentence (a marker counts as one word). Warm spoken Sinhala; {address} as the",
    "  vocative; no English; no written-register endings.",
    "- 2 to 4 sentences.",
    `- Vocabulary this concept may use for the first time: ${concept.vocabularyIntroduced.join(", ") || "(none new)"}.`,
    brief.type === "CHECK_MY_WORK" || brief.label.includes("analogy")
      ? `- If an analogy is called for, pick ONE domain from: ${ANALOGY_DOMAINS.join("; ")} and set analogyDomain.`
      : "",
    "",
    `THE BEAT: type ${brief.type}. ${brief.instructions}`,
    "",
    "=== THE CONCEPT'S DESIGN ENTRY ===",
    JSON.stringify(
      {
        objective: concept.objective,
        techniqueSequence: concept.techniqueSequence,
        sinhalaHandling: concept.sinhalaHandling,
        questionPatterns: concept.questionPatterns,
        misconceptionStops: concept.misconceptionStops,
        analogySlot: concept.analogySlot,
        officialExamples: concept.officialExamples,
      },
      null,
      1,
    ),
    "",
    "=== STYLE CARD ===",
    styleCard,
  ]
    .filter(Boolean)
    .join("\n");
}

function textbookVerbatim(): string[] {
  const strings: string[] = [];
  const walk = (value: unknown): void => {
    if (typeof value === "string") strings.push(value);
    else if (Array.isArray(value)) value.forEach(walk);
    else if (value && typeof value === "object") Object.values(value).forEach(walk);
  };
  walk(LESSON_1_NUMBERS_STEPS);
  return strings.filter((text) => text.length >= 8);
}

async function main() {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error("GEMINI_API_KEY is not set.");
  const ai = new GoogleGenAI({ apiKey });

  const design = JSON.parse(await readFile(DESIGN_PATH, "utf8")) as LessonDesign;
  const styleCard = await readFile(STYLE_PATH, "utf8");
  const denylist = new Set(design.denylistNumbers);
  const verbatim = textbookVerbatim();

  // Jaccard corpus (no embeddings here — the comparison is about writing
  // quality and constraint discipline; the full cosine gate runs in the
  // real author).
  const plan = JSON.parse(await readFile(TRANSCRIPT_PATH, "utf8")) as { segments: Array<{ fullTranscript: string }> };
  const corpus = [
    ...new Set(
      plan.segments.flatMap((segment) => sentencesOf(segment.fullTranscript)).map((sentence) => sentence.trim()),
    ),
  ]
    .filter((sentence) => stripOfficial(sentence, verbatim).length >= 12)
    .map((sentence) => ({ sentence, grams: charNgrams(stripOfficial(sentence, verbatim)) }));
  console.log(`Corpus: ${corpus.length} transcript sentences. Models: ${CANDIDATE_MODELS.join(", ")}\n`);

  const results: GenerationResult[] = [];
  for (const brief of BRIEFS) {
    const concept = design.concepts.find((c) => c.conceptTag === brief.concept);
    if (!concept) throw new Error(`design has no ${brief.concept}`);
    const prompt = buildPrompt(styleCard, design, concept, brief);
    for (const model of CANDIDATE_MODELS) {
      process.stdout.write(`  ${brief.concept} × ${model} … `);
      try {
        const response = await withRetry(() =>
          ai.models.generateContent({
            model,
            contents: [{ role: "user", parts: [{ text: prompt }] }],
            config: { responseMimeType: "application/json", responseJsonSchema: BEAT_SCHEMA, maxOutputTokens: 32768 },
          }),
        );
        const usage = response.usageMetadata;
        const parsed = JSON.parse(
          (response.text ?? "").trim().replace(/^```(?:json)?\s*/iu, "").replace(/\s*```$/u, ""),
        ) as { say?: string; analogyDomain?: string };
        const say = String(parsed.say ?? "").trim();
        const violations = [
          ...validateSay(say, brief.concept, denylist),
          ...degenerateBeatProblems({ say, analogyDomain: parsed.analogyDomain }),
        ].map((p: Problem) => `[${p.rule}] ${p.detail}`);
        let spoken = "";
        try {
          spoken = substituteNumbers(say).spoken;
        } catch (error) {
          violations.push(`[number] ${String(error).slice(0, 90)}`);
        }
        const hits = spoken ? surfaceSimilarity(spoken, corpus, verbatim) : [];
        const worst = hits.reduce((best, hit) => (hit.jaccard > best.jaccard ? hit : best), {
          jaccard: 0,
          closestTranscript: "",
          sentence: "",
          cosine: null,
        });
        if (worst.jaccard > MAX_JACCARD) violations.push(`[distance] Jaccard ${worst.jaccard.toFixed(2)} vs her: "${worst.closestTranscript.slice(0, 60)}"`);
        const sentences = sentencesOf(say.replace(/\{number:\d+\}/gu, "N"));
        results.push({
          model,
          brief,
          say,
          spoken,
          analogyDomain: parsed.analogyDomain ?? "",
          sentenceCount: sentences.length,
          maxSentenceWords: Math.max(0, ...sentences.map((sentence) => sentence.split(/\s+/u).filter(Boolean).length)),
          violations,
          maxJaccard: worst.jaccard,
          closest: worst.closestTranscript,
          inputTokens: usage?.promptTokenCount ?? 0,
          outputTokens: usage?.candidatesTokenCount ?? 0,
          thinkingTokens: usage?.thoughtsTokenCount ?? 0,
        });
        console.log(`ok (${violations.length} violation(s), J ${worst.jaccard.toFixed(2)})`);
      } catch (error) {
        if (/prepayment credits|spending cap/iu.test(String(error))) {
          console.error("\nSTOPPED: credits exhausted. Partial results below.");
          await report(results, design);
          process.exit(1);
        }
        console.log(`FAILED: ${String(error).slice(0, 90)}`);
        results.push({
          model,
          brief,
          say: "",
          spoken: "",
          analogyDomain: "",
          sentenceCount: 0,
          maxSentenceWords: 0,
          violations: [],
          maxJaccard: 0,
          closest: "",
          inputTokens: 0,
          outputTokens: 0,
          thinkingTokens: 0,
          failed: String(error).slice(0, 160),
        });
      }
    }
  }
  await report(results, design);
}

async function report(results: GenerationResult[], design: LessonDesign): Promise<void> {
  // One fixed blind mapping for the whole document.
  const shuffled = [...CANDIDATE_MODELS].sort(() => Math.random() - 0.5);
  const label = new Map(shuffled.map((model, index) => [model, String.fromCharCode(65 + index)]));

  const lines: string[] = [];
  lines.push("# Authoring-model comparison — judge the Sinhala blind");
  lines.push("");
  lines.push(
    `Eight representative beats, one per concept, each generated by three models with the same prompt and ` +
      `rules. Versions are labelled A/B/C consistently; the mapping is at the very bottom. For each: read ` +
      `the Sinhala first, then the metrics.`,
  );
  lines.push("");
  for (const brief of BRIEFS) {
    lines.push(`## ${brief.concept} — ${brief.label} (${brief.type})`);
    lines.push("");
    const byModel = results.filter((result) => result.brief === brief);
    for (const result of [...byModel].sort((a, b) => (label.get(a.model) ?? "").localeCompare(label.get(b.model) ?? ""))) {
      lines.push(`### Version ${label.get(result.model)}`);
      lines.push("");
      if (result.failed) {
        lines.push(`*generation failed: ${result.failed}*`);
        lines.push("");
        continue;
      }
      lines.push(`> ${result.spoken || result.say}`);
      lines.push("");
      if (result.analogyDomain) lines.push(`analogy: ${result.analogyDomain}`);
      lines.push(
        `sentences: ${result.sentenceCount} · longest: ${result.maxSentenceWords} words · ` +
          `max-similarity (Jaccard): ${result.maxJaccard.toFixed(2)} · violations: ${result.violations.length}`,
      );
      if (result.violations.length > 0) {
        lines.push("");
        for (const violation of result.violations) lines.push(`- ${violation}`);
      }
      lines.push("");
    }
  }
  lines.push("---");
  lines.push("");
  lines.push("## Model mapping (read the Sinhala first!)");
  lines.push("");
  for (const model of CANDIDATE_MODELS) lines.push(`- Version ${label.get(model)} = \`${model}\``);
  lines.push("");
  await mkdir(path.dirname(OUT_PATH), { recursive: true });
  await writeFile(OUT_PATH, `${lines.join("\n")}\n`, "utf8");

  // Cost summary.
  const totalLessonBeats = Math.round(
    design.concepts.reduce((sum, concept) => sum + concept.timeWeightMinutes, 0) * (60 / 13),
  );
  console.log(`\n${"=".repeat(70)}\nTOKEN SPEND (8 beats each)`);
  for (const model of CANDIDATE_MODELS) {
    const own = results.filter((result) => result.model === model && !result.failed);
    const input = own.reduce((sum, result) => sum + result.inputTokens, 0);
    const output = own.reduce((sum, result) => sum + result.outputTokens, 0);
    const thinking = own.reduce((sum, result) => sum + result.thinkingTokens, 0);
    const violations = results.filter((r) => r.model === model).reduce((sum, r) => sum + r.violations.length, 0);
    console.log(
      `  ${model.padEnd(26)} in ${input.toLocaleString().padStart(9)}  out ${output.toLocaleString().padStart(7)}  ` +
        `thinking ${thinking.toLocaleString().padStart(7)}  violations ${violations}`,
    );
    // Full-lesson projection: per-beat output scales linearly; input is
    // amortised in production (the real author generates ~10-beat chunks,
    // so charge input once per ~10 beats).
    const perBeatOut = (output + thinking) / Math.max(1, own.length);
    const perCallIn = input / Math.max(1, own.length);
    const projectedIn = (totalLessonBeats / 10) * perCallIn;
    const projectedOut = totalLessonBeats * perBeatOut;
    console.log(
      `    projected full lesson (~${totalLessonBeats} beats): ` +
        `in ~${Math.round(projectedIn / 1000)}K, out+thinking ~${Math.round(projectedOut / 1000)}K tokens`,
    );
  }
  console.log(`\nBlind review: docs/review/model-comparison.md (mapping at the bottom).`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
